import pandas as pd
import numpy as np
from typing import dict

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    invoices = inputs["invoices"].copy()
    payments = inputs["payments"].copy()

    # Initialize tracking structures
    allocations_list = []
    customer_credit_dict = {}

    # Track open amounts per invoice (initially the invoice amount)
    open_amounts = {}
    for _, row in invoices.iterrows():
        open_amounts[row['invoice_id']] = row['amount']

    # Track which invoices have been touched by any allocation
    invoices_touched = set()

    # Sort payments by paid_ts, then payment_id (oldest first)
    payments_sorted = payments.sort_values(['paid_ts', 'payment_id']).reset_index(drop=True)

    # Process each payment
    for _, payment in payments_sorted.iterrows():
        payment_id = payment['payment_id']
        customer_id = payment['customer_id']
        left = payment['amount']

        # Get invoices for this customer, filter to those with open_amount > 0
        customer_invoices = invoices[invoices['customer_id'] == customer_id].copy()

        # Sort by due_date, then invoice_id (oldest first)
        customer_invoices = customer_invoices.sort_values(['due_date', 'invoice_id']).reset_index(drop=True)

        # Allocate payment against invoices
        for _, invoice in customer_invoices.iterrows():
            invoice_id = invoice['invoice_id']
            current_open = open_amounts[invoice_id]

            if current_open > 0 and left > 0:
                # Pay the minimum of what's left and what's open on this invoice
                pay = min(left, current_open)

                # Update open amount
                open_amounts[invoice_id] -= pay
                left -= pay

                # Record allocation
                allocations_list.append({
                    'payment_id': payment_id,
                    'invoice_id': invoice_id,
                    'applied_amount': pay
                })

                # Mark invoice as touched
                invoices_touched.add(invoice_id)

                if left == 0:
                    break

        # Any remaining amount becomes unapplied credit
        if left > 0:
            if customer_id not in customer_credit_dict:
                customer_credit_dict[customer_id] = 0.0
            customer_credit_dict[customer_id] += left

    # Build invoice_status output
    invoice_status_list = []
    for _, invoice in invoices.iterrows():
        invoice_id = invoice['invoice_id']
        open_amount = open_amounts[invoice_id]

        if open_amount == 0:
            status = 'PAID'
        elif invoice_id not in invoices_touched:
            status = 'OPEN'
        else:
            status = 'PARTIAL'

        invoice_status_list.append({
            'invoice_id': invoice_id,
            'open_amount': open_amount,
            'status': status
        })

    # Build allocations output
    allocations_df = pd.DataFrame(allocations_list)
    if allocations_df.empty:
        allocations_df = pd.DataFrame(columns=['payment_id', 'invoice_id', 'applied_amount'])
        allocations_df = allocations_df.astype({
            'payment_id': 'int64',
            'invoice_id': 'int64',
            'applied_amount': 'float64'
        })
    else:
        allocations_df = allocations_df.astype({
            'payment_id': 'int64',
            'invoice_id': 'int64',
            'applied_amount': 'float64'
        })

    # Build customer_credit output
    customer_credit_list = []
    for customer_id, unapplied_amount in customer_credit_dict.items():
        if unapplied_amount > 0:
            customer_credit_list.append({
                'customer_id': customer_id,
                'unapplied_amount': unapplied_amount
            })

    customer_credit_df = pd.DataFrame(customer_credit_list)
    if customer_credit_df.empty:
        customer_credit_df = pd.DataFrame(columns=['customer_id', 'unapplied_amount'])
        customer_credit_df = customer_credit_df.astype({
            'customer_id': 'int64',
            'unapplied_amount': 'float64'
        })
    else:
        customer_credit_df = customer_credit_df.astype({
            'customer_id': 'int64',
            'unapplied_amount': 'float64'
        })

    # Build invoice_status output dataframe
    invoice_status_df = pd.DataFrame(invoice_status_list)
    invoice_status_df = invoice_status_df.astype({
        'invoice_id': 'int64',
        'open_amount': 'float64',
        'status': 'object'
    })

    return {
        'invoice_status': invoice_status_df,
        'allocations': allocations_df,
        'customer_credit': customer_credit_df
    }
